const S = size, H = height, n = Math.max(1, Math.round(blobs)), s = seed;
for (let i = 0; i < n; i++) {
  const a = TAU * (i / n + 0.3 * rand(i, s, 1)), d = n === 1 ? 0 : S * (0.12 + 0.18 * rand(i, s, 2)) * (i === 0 ? 0 : 1);
  const r = S * (0.22 + 0.12 * rand(i, s, 3)) * (i === 0 ? 1.25 : 1);
  const ry = Math.min(r, H * (i === 0 ? 0.62 : 0.5));
  const q = addpoint(0, [Math.cos(a) * d, ry * 0.75, Math.sin(a) * d]);
  setpointattrib(0, 'scale', q, [r, ry, r]);
  setpointattrib(0, 'orient', q, quaternion(radians(360 * rand(i, s, 5)), [0, 1, 0]));
  setpointattrib(0, 'tint', q, 0.8 + 0.35 * rand(i, s, 4));
}
